import type { ManualBundle } from './model.js';

export function bundleModuleSource(bundle: ManualBundle): string {
  const header =
    '// Generated by src/manual/build.ts from docs/user/*.md. Do not edit.\n' +
    "import type { ManualBundle } from '../../../../src/manual/model.js';\n\n";
  return `${header}export const MANUAL: ManualBundle = ${JSON.stringify(bundle, null, 2)};\n`;
}
